<?php
use yii\helpers\Html;
use yii\widgets\ActiveForm;
$this->title = Yii::t('app', 'Email settings'); $this->params['breadcrumbs'][] = $this->title;
?>
<div class="settings-page"><header class="settings-hero"><div><p class="text-overline"><?= Yii::t('app', 'Notifications') ?></p><h1><?= Html::encode($this->title) ?></h1><p class="text-muted"><?= Yii::t('app', 'Configure SMTP and form notification recipients.') ?></p></div></header>
<div class="card"><?php $form = ActiveForm::begin(); ?><?= $form->errorSummary($model) ?><div class="form-grid"><?= $form->field($model,'smtpHost')->textInput(['dir'=>'ltr']) ?><?= $form->field($model,'smtpPort')->input('number') ?><?= $form->field($model,'smtpUsername')->textInput(['dir'=>'ltr']) ?><?= $form->field($model,'smtpPassword')->passwordInput(['autocomplete'=>'new-password','placeholder'=>Yii::t('app','Leave blank to keep the current password')]) ?><?= $form->field($model,'smtpEncryption')->dropDownList([''=>Yii::t('app','None'),'tls'=>'TLS','ssl'=>'SSL']) ?><?= $form->field($model,'fromEmail')->textInput(['dir'=>'ltr']) ?><?= $form->field($model,'fromName')->textInput() ?><?= $form->field($model,'notificationEmail')->textInput(['dir'=>'ltr']) ?></div><div class="email-toggle-list"><?= $form->field($model,'fileTransport')->checkbox() ?><fieldset><legend><?= Yii::t('app','Form notifications') ?></legend><?= $form->field($model,'notifyContact')->checkbox() ?><?= $form->field($model,'notifyOrder')->checkbox() ?><?= $form->field($model,'notifyOpportunity')->checkbox() ?><?= $form->field($model,'notifyAdmins')->checkbox() ?></fieldset></div><div class="form-actions email-form-actions"><?= Html::submitButton(\frontend\widgets\Icon::show('activity') . Yii::t('app','Test connection'),['class'=>'btn btn-secondary','name'=>'test-email','value'=>'1','formnovalidate'=>false]) ?><?= Html::submitButton(\frontend\widgets\Icon::show('save') . Yii::t('app','Save'),['class'=>'btn']) ?></div><?php ActiveForm::end(); ?></div></div>
